\begin{equation}
    \hat{s}_{t+1} = \arg\max_{s_{t+1}} \; P(s_{t+1} \mid D_t, p, u_{t+1}, \mathcal{M})
\end{equation}

\begin{equation}
    \hat{a}_{t+1} = \arg\max_{a_{t+1}} \; P(a_{t+1} \mid D_t, p, \hat{s}_{t+1}, \mathcal{M})
\end{equation}

\begin{equation}
    \hat{r}_{t+1} = \arg\max_{r_{t+1}} \; P(r_{t+1} \mid D_t, p, u_{t+1}, \hat{a}_{t+1}, \mathcal{M})
\end{equation}

\begin{equation}
a_t^* = \arg\max_{a_t} \left[ Q(d_t, a_t) + w \sqrt{\frac{\ln N(d_t)}{N(c(d_t, a_t))}} \right]
\end{equation}

\begin{equation}
Q(d_t, a_t) = \lambda \cdot \left( \mathcal{L}(d_t, a_t) + \left(1 - \lambda\right) \cdot \mathrm{T}(d_t, a_t) \right)
\end{equation}

